#!/usr/bin/env python3
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-25 — feasibility probe: parse one Autoware TU with libclang using
# its compile_commands.json flags and list class methods, member writes/reads, publish calls, subscription creations.
import json, sys, time, re
import clang.cindex as ci
ci.Config.set_library_file('/usr/lib/llvm-14/lib/libclang-14.so.1')
cc = json.load(open(sys.argv[1])); src = [c for c in cc if c['file'].endswith(sys.argv[2])][0]
args = src.get('arguments') or src['command'].split()
# keep only flags: drop compiler, -o X, -c, the file
flags = []; skip = False
for a in args[1:]:
    if skip: skip = False; continue
    if a in ('-o', '-c'): skip = (a == '-o'); continue
    if a == src['file'] or a.endswith('.cpp') or a.endswith('.cc'): continue
    flags.append(a)
import glob, os
rd = sorted(glob.glob('/usr/lib/llvm-14/lib/clang/*'))[-1]
flags += ['-resource-dir', rd, '-isystem', os.path.join(rd, 'include')]
t0 = time.time(); idx = ci.Index.create()
tu = idx.parse(src['file'], args=flags, options=ci.TranslationUnit.PARSE_DETAILED_PROCESSING_RECORD | ci.TranslationUnit.PARSE_SKIP_FUNCTION_BODIES * 0)
errs = [d for d in tu.diagnostics if d.severity >= ci.Diagnostic.Error]
print(f'parsed {src["file"].split("/")[-1]} in {time.time()-t0:.1f}s, errors {len(errs)}', [str(e)[:100] for e in errs[:2]])
K = ci.CursorKind
def in_main(c): return c.location.file and c.location.file.name == src['file']
for c in tu.cursor.walk_preorder():
    if c.kind == K.CXX_METHOD and in_main(c) and c.is_definition():
        cls = c.semantic_parent.spelling
        writes, reads, calls, pubs, subs = set(), set(), set(), set(), []
        for n in c.walk_preorder():
            if n.kind == K.MEMBER_REF_EXPR and n.referenced is not None and n.referenced.kind == K.FIELD_DECL:
                # member of this class?
                if n.referenced.semantic_parent.spelling == cls: reads.add(n.spelling)
            if n.kind == K.CALL_EXPR:
                nm = n.spelling
                if nm == 'publish': pubs.add(n.displayname)
                if nm.startswith('create_subscription') or nm.startswith('create_wall_timer') or nm == 'registerCallback': subs.append(nm)
                if nm in ('push_back', 'emplace_back', 'push_front', 'clear', 'reset', 'insert', 'emplace', 'pop_front', 'erase', 'operator='):
                    # object expression = first child
                    ch = list(n.get_children())
                    obj = ch[0] if ch else None
                    txt = ''.join(t.spelling for t in obj.get_tokens()) if obj is not None else '?'
                    writes.add(f'{nm}({txt[:40]})')
            if n.kind == K.BINARY_OPERATOR:
                toks = [t.spelling for t in n.get_tokens()]
                if '=' in toks:
                    ch = list(n.get_children())
                    if ch and ch[0].kind == K.MEMBER_REF_EXPR: writes.add(f'assign({ch[0].spelling})')
        print(f'  {cls}::{c.spelling}  reads={sorted(reads)[:8]}  writes={sorted(writes)[:6]}  publish={len(pubs)}  creates={subs[:3]}')
